import React from 'react';

import { IClub } from '@apps/Clubs/@types/clubs.types';
import OneClub from '@apps/Clubs/components/OneClub';
import PageHeader from '@components/PageHeader';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohContainer from '@ui-kit/layout/Container';

interface IClubsOnePageProps {
  id: number;
}

const ClubsOnePage: React.FC<IClubsOnePageProps> = ({ id }) => {
  const [data, setData] = React.useState<IClub>();

  return (
    <div>
      <Breadcrumb
        data={[
          { href: '/clubs', text: 'Клубы' },
          { href: `/clubs/${id}`, text: data?.name ?? '...', active: true },
        ]}
      />
      <PohContainer>
        <PageHeader title={data?.name ?? '...'}>&nbsp;</PageHeader>
        <OneClub id={id} onDataReady={setData} />
      </PohContainer>
    </div>
  );
};

export default ClubsOnePage;
